SELECT r.id, r.protocol_revision, r.protocol_run_id, r.protocol_parent_run_id, r.protocol_prior_run_id, r.protocol_client_message_id, r.protocol_turn_id, r.protocol_resumed_by_run_id, r.protocol_input_json, r.protocol_pending_json, r.protocol_last_sequence, r.effective_user_id, r.protocol_key, r.protocol_status, r.protocol_input_hash, r.protocol_source_key, r.protocol_initial_turn_key, r.conversation_id, r.run_kind FROM (SELECT * FROM  (SELECT c.id, c.conversation_id, c.run_kind, c.effective_user_id, c.protocol_key, c.protocol_run_id, c.protocol_parent_run_id, c.protocol_prior_run_id, c.protocol_client_message_id, c.protocol_turn_id, c.protocol_status, c.protocol_input_hash, c.protocol_input_json, c.protocol_revision, c.protocol_last_sequence, c.protocol_pending_json, c.protocol_resumed_by_run_id, c.protocol_source_key, c.protocol_initial_turn_key FROM run c WHERE c.run_kind = 'agui' AND c.effective_user_id = $Principal
)  agui_data) r WHERE $criteria.CompositeIn("r", $WriterKeys)